import sys
import csv
import json

def main():
    category = sys.argv[1] if len(sys.argv) > 1 else None
    reader = csv.DictReader(sys.stdin)
    totals = {}

    for row in reader:
        if category and row['category'] != category:
            continue
        totals[row['category']] = totals.get(row['category'], 0) + float(row['amount'])

    if totals:
        totals = {category: f"{total:.2f}" for category, total in totals.items()}
        print(json.dumps(totals))
    else:
        print("No expenses found.")

if __name__ == "__main__":
    main()

import sys

def print_board(board):
    for row in board:
        print(" ".join(row))

def check_win(board, player):
    for row in board:
        if all(cell == player for cell in row):
            return True
    for col in range(3):
        if all(board[row][col] == player for row in range(3)):
            return True
    if all(board[i][i] == player for i in range(3)) or all(board[i][2-i] == player for i in range(3)):
        return True
    return False

def check_draw(board):
    return all(cell != " " for row in board for cell in row)

def get_player_input(board):
    while True:
        try:
            square = int(input("Enter square number (1-9): "))
            if square < 1 or square > 9:
                raise ValueError
            if board[square-1][square-1] != " ":
                raise ValueError
            return square-1
        except ValueError:
            print("Invalid move. Please enter a number between 1 and 9.")

def switch_player(player):
    return "O" if player == "X" else "X"

def main():
    board = [[" " for _ in range(3)] for _ in range(3)]
    player = "X"
    print_board(board)
    while True:
        square = get_player_input(board)
        board[square][square] = player
        print_board(board)
        if check_win(board, player):
            print(f"{player} wins!")
            break
        elif check_draw(board):
            print("Draw!")
            break
        player = switch_player(player)

if __name__ == "__main__":
    main()

import argparse
import json
import os

def main():
    parser = argparse.ArgumentParser(description="Directory Inventory")
    parser.add_argument("directory", help="Directory to inventory")
    parser.add_argument("--suffix", help="Suffix to filter files by", default="")
    args = parser.parse_args()

    inventory = {}
    for root, dirs, files in os.walk(args.directory):
        for file in files:
            if args.suffix and not file.endswith(args.suffix):
                continue
            path = os.path.join(root, file)
            inventory[path] = os.path.getsize(path)

    print(json.dumps(inventory, indent=4))

if __name__ == "__main__":
    main()

import argparse
import json
import sys

def validate_transaction(transaction):
    if not transaction:
        return False
    if not isinstance(transaction, dict) or "id" not in transaction or "cents" not in transaction:
        return False
    if not isinstance(transaction["id"], str) or not isinstance(transaction["cents"], int):
        return False
    return True

def main():
    parser = argparse.ArgumentParser(description="Validate transactions in a JSONL file")
    parser.add_argument("file", type=str, help="JSONL file containing transactions")
    args = parser.parse_args()

    total_cents = 0
    line_number = 0

    try:
        with open(args.file, "r") as file:
            for line in file:
                line_number += 1
                transaction = json.loads(line.strip())
                if not validate_transaction(transaction):
                    print(f"Invalid transaction on line {line_number}: {transaction}", file=sys.stderr)
                    sys.exit(1)
                total_cents += transaction["cents"]
    except FileNotFoundError:
        print(f"File not found: {args.file}", file=sys.stderr)
        sys.exit(1)

    print(f"Total cents: {total_cents}")

if __name__ == "__main__":
    main()

import json
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <json_file>")
        sys.exit(1)

    json_file = sys.argv[1]
    try:
        with open(json_file, 'r') as file:
            data = json.load(file)
    except FileNotFoundError:
        print(f"Error: File {json_file} not found.")
        sys.exit(1)

    score = 0
    for question in data:
        print(question["question"])
        answers = question["answers"]
        for answer in answers:
            print(answer)
            user_answer = input().strip().lower()
            if user_answer == answer.lower():
                score += 1
        print()

    print(f"Score: {score}/{len(data)}")

if __name__ == "__main__":
    main()
